export interface OperationConfig {
  /**
   * Whether or not the response should be included in the value returned from
   * an operation.
   *
   * If set to `true`, a tuple of `[A, HttpClientResponse]` will be returned,
   * where `A` is the success type of the operation.
   *
   * If set to `false`, only the success type of the operation will be returned.
   */
  readonly includeResponse?: boolean | undefined
}

/**
 * A utility type which optionally includes the response in the return result
 * of an operation based upon the value of the `includeResponse` configuration
 * option.
 */
export type WithOptionalResponse<A, Config extends OperationConfig> = Config extends {
  readonly includeResponse: true
} ? [A, HttpClientResponse.HttpClientResponse] : A

export const make = (
  httpClient: HttpClient.HttpClient,
  options: {
    readonly transformClient?: ((client: HttpClient.HttpClient) => Effect.Effect<HttpClient.HttpClient>) | undefined
  } = {}
): PostcodesFull => {
  const unexpectedStatus = (response: HttpClientResponse.HttpClientResponse) =>
    Effect.flatMap(
      Effect.orElseSucceed(response.json, () => "Unexpected status code"),
      (description) =>
        Effect.fail(
          new HttpClientError.HttpClientError({
            reason: new HttpClientError.StatusCodeError({
              request: response.request,
              response,
              description: typeof description === "string" ? description : JSON.stringify(description),
            }),
          }),
        ),
    )
  const withResponse = <Config extends OperationConfig>(config: Config | undefined) => (
    f: (response: HttpClientResponse.HttpClientResponse) => Effect.Effect<any, any>,
  ): (request: HttpClientRequest.HttpClientRequest) => Effect.Effect<any, any> => {
    const withOptionalResponse = (
      config?.includeResponse
        ? (response: HttpClientResponse.HttpClientResponse) => Effect.map(f(response), (a) => [a, response])
        : (response: HttpClientResponse.HttpClientResponse) => f(response)
    ) as any
    return options?.transformClient
      ? (request) =>
          Effect.flatMap(
            Effect.flatMap(options.transformClient!(httpClient), (client) => client.execute(request)),
            withOptionalResponse
          )
      : (request) => Effect.flatMap(httpClient.execute(request), withOptionalResponse)
  }
  const decodeSuccess =
    <Schema extends Schema.Constraint>(schema: Schema) =>
    (response: HttpClientResponse.HttpClientResponse) =>
      HttpClientResponse.schemaBodyJson(schema)(response)
  const decodeError =
    <const Tag extends string, Schema extends Schema.Constraint>(tag: Tag, schema: Schema) =>
    (response: HttpClientResponse.HttpClientResponse) =>
      Effect.flatMap(
        HttpClientResponse.schemaBodyJson(schema)(response),
        (cause) => Effect.fail(PostcodesFullError(tag, cause, response)),
      )
  return {
    httpClient,
    "LookupPostcode": (postcode, options) => HttpClientRequest.get(`/postcodes/${postcode}`).pipe(
    withResponse(options?.config)(HttpClientResponse.matchStatus({
      "2xx": decodeSuccess(LookupPostcode200),
      orElse: unexpectedStatus
    }))
  ),
    "PostcodeLookup": (options) => HttpClientRequest.get(`/postcodes`).pipe(
    HttpClientRequest.setUrlParams({ "query": options?.params?.["query"] as any, "limit": options?.params?.["limit"] as any, "longitude": options?.params?.["longitude"] as any, "latitude": options?.params?.["latitude"] as any, "radius": options?.params?.["radius"] as any, "widesearch": options?.params?.["widesearch"] as any, "filter": options?.params?.["filter"] as any }),
    withResponse(options?.config)(HttpClientResponse.matchStatus({
      "2xx": decodeSuccess(PostcodeLookup200),
      orElse: unexpectedStatus
    }))
  ),
    "BulkPostcodeLookup": (options) => HttpClientRequest.post(`/postcodes`).pipe(
    withResponse(options?.config)(HttpClientResponse.matchStatus({
      "2xx": decodeSuccess(BulkPostcodeLookup200),
      orElse: unexpectedStatus
    }))
  ),
    "NearestPostcode": (postcode, options) => HttpClientRequest.get(`/postcodes/${postcode}/nearest`).pipe(
    withResponse(options?.config)(HttpClientResponse.matchStatus({
      "2xx": decodeSuccess(NearestPostcode200),
      orElse: unexpectedStatus
    }))
  ),
    "randomPostcode": (options) => HttpClientRequest.get(`/random/postcodes`).pipe(
    HttpClientRequest.setUrlParams({ "outcode": options?.params?.["outcode"] as any }),
    withResponse(options?.config)(HttpClientResponse.matchStatus({
      "2xx": decodeSuccess(RandomPostcode200),
      orElse: unexpectedStatus
    }))
  ),
    "LookupTerminatedPostcode": (postcode, options) => HttpClientRequest.get(`/terminated_postcodes/${postcode}`).pipe(
    withResponse(options?.config)(HttpClientResponse.matchStatus({
      "2xx": decodeSuccess(LookupTerminatedPostcode200),
      "404": () => Effect.void,
      orElse: unexpectedStatus
    }))
  ),
    "getScottishPostcode": (postcode, options) => HttpClientRequest.get(`/scotland/postcodes/${postcode}`).pipe(
    withResponse(options?.config)(HttpClientResponse.matchStatus({
      "2xx": decodeSuccess(GetScottishPostcode200),
      "404": () => Effect.void,
      orElse: unexpectedStatus
    }))
  ),
    "FindOutcode": (outcode, options) => HttpClientRequest.get(`/outcodes/${outcode}`).pipe(
    withResponse(options?.config)(HttpClientResponse.matchStatus({
      "2xx": decodeSuccess(FindOutcode200),
      orElse: unexpectedStatus
    }))
  ),
    "PlaceQuery": (options) => HttpClientRequest.get(`/places`).pipe(
    withResponse(options?.config)(HttpClientResponse.matchStatus({
      "2xx": decodeSuccess(PlaceQuery200),
      orElse: unexpectedStatus
    }))
  ),
    "FindPlace": (code, options) => HttpClientRequest.get(`/places/${code}`).pipe(
    withResponse(options?.config)(HttpClientResponse.matchStatus({
      "2xx": decodeSuccess(FindPlace200),
      orElse: unexpectedStatus
    }))
  ),
    "randomPlace": (options) => HttpClientRequest.get(`/random/places`).pipe(
    withResponse(options?.config)(HttpClientResponse.matchStatus({
      "2xx": decodeSuccess(RandomPlace200),
      orElse: unexpectedStatus
    }))
  )
  }
}

export interface PostcodesFull {
  readonly httpClient: HttpClient.HttpClient
  /**
* ### Postcode Data
* 
* Lookup a UK postcode against the ONS Postcode Directory (ONSPD). The response is a fully resolved record — every administrative, electoral, statistical and health geography that ONSPD ships for the postcode is returned at the top level by its human-readable name, with the equivalent GSS / official codes mirrored under the `codes` object.
* 
* The same shape is returned by `/postcodes` (bulk + search) and the reverse-geocoding endpoints. `/outcodes` returns a separate, aggregated [Outcode](#tag/Outward-Codes) shape — one row per outward code, with admin / parish / constituency arrays summarising the postcodes inside.
* 
* Returns `404` if the postcode does not exist or is not valid.
*/
readonly "LookupPostcode": <Config extends OperationConfig>(postcode: string, options: { readonly config?: Config | undefined } | undefined) => Effect.Effect<WithOptionalResponse<typeof LookupPostcode200.Type, Config>, HttpClientError.HttpClientError | SchemaError>
  /**
* Query for a postcode either by:
* 
* - The postcode itself (with `query=`) or by,
* - A geolocation (`lat=` and `lon=`).
* 
* ## Query with Postcode
* 
* Submit a postcode query and receive a complete list of postcode matches and all associated postcode data. This is triggered when `query=` is supplied.
* 
* This is essentially a postcode search which prefix matches and returns postcodes in sorted order (case insensitive).
* 
* This method is space sensitive, i.e. it detects for spaces between outward and inward parts of the postcode (some examples detailed in this [issue](https://github.com/ideal-postcodes/postcodes.io/issues/44)).
* 
* The result set can either be empty or populated with up to 100 postcode entities. Either way it will always return a 200 response code.
* 
* ## Query with Geolocation
* 
* Returns nearest postcodes for a given longitude and latitude. This is triggered when `lat=` and `lon=` are supplied.
*/
readonly "PostcodeLookup": <Config extends OperationConfig>(options: { readonly params?: typeof PostcodeLookupParams.Encoded | undefined; readonly config?: Config | undefined } | undefined) => Effect.Effect<WithOptionalResponse<typeof PostcodeLookup200.Type, Config>, HttpClientError.HttpClientError | SchemaError>
  /**
* Accepts a JSON object containing an array of postcodes. Returns a list of matching postcodes and respective available data.
* 
* Be sure to submit JSON requests setting `Content-Type` to `application/json`.
* 
* Accepts up to 100 postcodes.
* 
* ### Post Data
* 
* This method requires a JSON object containing an array of postcodes to be posted, e.g.
* 
* ```json
* {
*   "postcodes": ["PR3 0SG", "M45 6GN", "EX16 5BL"]
* }
* ```
* 
* ## Bulk Reverse Geocoding
* 
* Bulk translates geolocations into Postcodes. Accepts up to 100 geolocations.
*/
readonly "BulkPostcodeLookup": <Config extends OperationConfig>(options: { readonly config?: Config | undefined } | undefined) => Effect.Effect<WithOptionalResponse<typeof BulkPostcodeLookup200.Type, Config>, HttpClientError.HttpClientError | SchemaError>
  /**
* Returns a list of postcodes geographically nearest to the specified postcode, ordered by proximity (closest first).
*/
readonly "NearestPostcode": <Config extends OperationConfig>(postcode: string, options: { readonly config?: Config | undefined } | undefined) => Effect.Effect<WithOptionalResponse<typeof NearestPostcode200.Type, Config>, HttpClientError.HttpClientError | SchemaError>
  /**
* Returns a randomly selected postcode along with comprehensive geographic, administrative, and statistical data associated with that postcode.
*/
readonly "randomPostcode": <Config extends OperationConfig>(options: { readonly params?: typeof RandomPostcodeParams.Encoded | undefined; readonly config?: Config | undefined } | undefined) => Effect.Effect<WithOptionalResponse<typeof RandomPostcode200.Type, Config>, HttpClientError.HttpClientError | SchemaError>
  /**
* Lookup a terminated postcode.
* 
* If the terminated postcode exists, this API returns the year and month of termination plus its last known WGS84 coordinates. Channel Islands and Isle of Man postcodes do not carry coordinates — `longitude` and `latitude` will be `null` for those.
* 
* Returns `404` if the postcode does not exist in our database of terminated postcodes or is not valid.
* 
* Source: ONS Postcode Directory (ONSPD). Live and terminated postcodes share the same underlying table; a postcode is terminated when `date_of_termination` is set.
*/
readonly "LookupTerminatedPostcode": <Config extends OperationConfig>(postcode: string, options: { readonly config?: Config | undefined } | undefined) => Effect.Effect<WithOptionalResponse<typeof LookupTerminatedPostcode200.Type, Config>, HttpClientError.HttpClientError | SchemaError>
  /**
* Lookup a Scottish postcode.
* 
* Returns Scottish Postcode Directory (SPD) data associated with the postcode. The response covers the full SPD field set: council area, electoral ward, Scottish and UK parliamentary geographies, health board, integration authority, data zone, intermediate zone, output area, locality, settlement, civil parish, island, national park, travel-to-work area, ITL/LAU, urban-rural classification, SIMD rank, ROA, census counts, and the corresponding GSS / official codes under the `codes` object.
* 
* Top-level fields hold the latest (canonical) value for each datapoint. Year-suffixed fields surface prior versions where the SPD publishes them.
* 
* Returns `404` if the postcode does not exist in SPD or is not valid.
* 
* For postcodes not in SPD but present in ONSPD (i.e. non-Scottish postcodes), a `404` is returned with the error message "Postcode exists in ONSPD but not in SPD."
* 
* Source: Scottish Postcode Directory (National Records of Scotland).
*/
readonly "getScottishPostcode": <Config extends OperationConfig>(postcode: string, options: { readonly config?: Config | undefined } | undefined) => Effect.Effect<WithOptionalResponse<typeof GetScottishPostcode200.Type, Config>, HttpClientError.HttpClientError | SchemaError>
  /**
* Returns aggregated information for postcodes grouped by their shared outward code.
* 
* The outward code is the first half of any postcode (3-4 characters and followed by a space). E.g. `SW1A` is the outward code for `SW1A 1AA`.
*/
readonly "FindOutcode": <Config extends OperationConfig>(outcode: string, options: { readonly config?: Config | undefined } | undefined) => Effect.Effect<WithOptionalResponse<typeof FindOutcode200.Type, Config>, HttpClientError.HttpClientError | SchemaError>
  /**
* Submit a place query and receive a complete list of places matches and associated data.
*/
readonly "PlaceQuery": <Config extends OperationConfig>(options: { readonly config?: Config | undefined } | undefined) => Effect.Effect<WithOptionalResponse<typeof PlaceQuery200.Type, Config>, HttpClientError.HttpClientError | SchemaError>
  /**
* Submit a place query and receive a complete list of place matches and associated data.
* 
* This API uses the Ordnance Survey Open Names Dataset. Places are not available for Northern Ireland.
*/
readonly "FindPlace": <Config extends OperationConfig>(code: string, options: { readonly config?: Config | undefined } | undefined) => Effect.Effect<WithOptionalResponse<typeof FindPlace200.Type, Config>, HttpClientError.HttpClientError | SchemaError>
  /**
* Returns a randomly selected place from the database along with all its associated geographical and administrative data. Useful for testing or displaying sample location data.
*/
readonly "randomPlace": <Config extends OperationConfig>(options: { readonly config?: Config | undefined } | undefined) => Effect.Effect<WithOptionalResponse<typeof RandomPlace200.Type, Config>, HttpClientError.HttpClientError | SchemaError>
}

export interface PostcodesFullError<Tag extends string, E> {
  readonly _tag: Tag
  readonly request: HttpClientRequest.HttpClientRequest
  readonly response: HttpClientResponse.HttpClientResponse
  readonly cause: E
}

class PostcodesFullErrorImpl extends Data.Error<{
  _tag: string
  cause: any
  request: HttpClientRequest.HttpClientRequest
  response: HttpClientResponse.HttpClientResponse
}> {}

export const PostcodesFullError = <Tag extends string, E>(
  tag: Tag,
  cause: E,
  response: HttpClientResponse.HttpClientResponse,
): PostcodesFullError<Tag, E> =>
  new PostcodesFullErrorImpl({
    _tag: tag,
    cause,
    response,
    request: response.request,
  }) as any
